svg.script:
(function(){
var D=[{"about":"Your task in your own words, or the note of a cleanup the last run dropped. Setup makes the run's state folder and env first; the main checkout must be on the main branch with no uncommitted changes.","src":"SKILL.md#1-setup","id":"task","code":"r1s1","name":"Task","x":120,"y":200},{"about":"One live agent run by the skill, not a workflow: it reads the repo once and gets each answer as a message. It critiques the task, finds the test command, and asks up to 4 independent questions at a time, about 8 in all. It stops once nothing important is unclear. Without the Agent tool the plan workflow runs it instead.","src":"assets/prompts/investigator.md, SKILL.md#2a-live-investigator","id":"investigator","code":"r1s2","name":"Investigator ant","x":440,"y":200},{"about":"The only time Ishikari asks you anything. Questions come through /ask-simple, up to 4 at a time, about 8 in all. Answering approves the whole run, merge to main included.","src":"SKILL.md#2a-live-investigator","id":"you","code":"r1s4","name":"You","x":440,"y":90},{"about":"Up to 5 at once, 2 bursts per question. They search the web and the whole computer, read only, never secrets, and report back. The investigator waits for them. Not logged when the live investigator sends them.","src":"SKILL.md#limits","id":"researchers","code":"r1s3","name":"Researcher ants","x":440,"y":300},{"about":"Goal, scope, every decision you made, facts with sources, constraints, risks, assumptions, acceptance checks and commands. Every claim cites an answer, a fact or the repo. Later ants read it instead of asking you. The main session never edits it.","src":"<state>/plans/<run>/investigation_report.md","id":"report","code":"r1s5","name":"investigation_report.md","x":780,"y":200},{"about":"Reads only the report and the repo; the report wins. Drafts the entry with /add-requirement and shows it can be built, with a throwaway spike only if needed. Never asks, designs or plans. The main session pipes the entry into ishikari.py req add. Runs only when setup finds requirements.org or requirements/*.org.","src":"scripts/ishikari-plan.js (Requirement phase)","id":"add-requirement","code":"r1s6","name":"Add requirement ant","x":1100,"y":200},{"about":"Designs the parts of the change, the files each owns, and every name, interface and data shape between them, so parallel workers fit. Maps each acceptance check to a part. Splits the work into tasks of about 3 files, no two editing one file, each with its own test file.","src":"scripts/ishikari-plan.js (Design phase)","id":"architect","code":"r1s8","name":"Architect ant","x":1420,"y":200},{"about":"Workers cannot ask questions, so each plan is complete: title, files, after. The plan script rejects bad or unknown ids, loops in after, two tasks on one file, and a bad requirement, before anything is built.","src":"<state>/plans/<run>/<task>.md","id":"plans","code":"r1s9","name":"Worker plans","x":1700,"y":200},{"about":"A recfile the logbook clerk appends to the moment an ant replies, one clerk at a time. Build and finish add a summary at the end. No ant reads it; read it with ishikari.py log status, recsel or an editor.","src":"~/.ishikari/<repo>-<hash>/logbook.rec","id":"logbook","code":"r1s7","name":"Logbook","x":1370,"y":40},{"about":"Up to 5 at a time, each in its own git worktree. Writes code, tests and the docs its change affects, decides on its own and commits all its work. A worker that gets stuck says why, and that becomes a bug for the next fix round. A plan may name a saved workflow to run instead.","src":"scripts/ishikari-build.js","id":"workers","code":"r2s1","name":"Worker ants","x":200,"y":540},{"about":"One per task, started as soon as it is built. Checks the work against its plan and architecture.md, and runs the tests. Each bug comes back with how to see it, its cause and a fix plan; a worker builds the fix and the detective re-checks. 3 tries per bug, 3 fix rounds, then the task drops. Never changes code. A dropped task's branch is kept for a later look, tasks built on it drop too, and the final report lists them.","src":"scripts/ishikari-build.js","id":"detectives","code":"r2s2","name":"Detective ants","x":760,"y":540},{"about":"Two tasks can pass alone and break together. It merges every passing task in a straight line in a throwaway copy and runs the tests once. A clashing task takes in the tasks it clashes with and goes back through the fix loop; 2 rounds. Skipped with fewer than 2 passing tasks.","src":"scripts/ishikari-build.js (Combined phase)","id":"integrator","code":"r2s3","name":"Integrator ant","x":1200,"y":540},{"about":"Adds every passing task's commits in a straight line, in dependency order, in a scratch copy, and tests once. It reuses build's trial merge when nothing moved. Then it checks its own merge with git cherry and counts changed lines with git diff --shortstat. Never touches main. A conflict, failed tests, or a task git finds missing goes back to the worker ant on its own branch: it merges the current main, fixes the bug, the detective re-checks, the integrator tests again, and finish retries the merge. Tasks that merged cleanly are not rebuilt. At most 2 extra build rounds; what is left drops and is reported.","src":"scripts/ishikari-finish.js (Merge phase)","id":"merger","code":"r3s1","name":"Merger ant","x":200,"y":1080},{"about":"Finds dead code, bloat and duplication from the merged tasks only. In its own worktree it edits, runs the tests and commits, and lands the cleanup only if they pass. Skipped under 100 changed lines, and a cleanup run gets no janitor. Tests failing: the cleanup is dropped, main moves with the tasks alone, its branch is kept, and its note goes to the next run's Task, where the investigator may ask about it.","src":"scripts/ishikari-finish.js (Upkeep phase)","id":"janitor","code":"r3s2","name":"Janitor ant","x":760,"y":1080},{"about":"One per merged task, up to 5 at once, only with 3 or more merged tasks. Each scores its task against that task's plan, and the judge weighs their reports.","src":"scripts/ishikari-finish.js","id":"jurors","code":"r4s1","name":"Juror ants","x":160,"y":1520},{"about":"Reads the investigation report, architecture and every worker plan, and the merged code with the cleanup on top. One question: does the code match the plans? The score is its own call, not an average. 7 or more, or no gaps: main moves. Below 7 with gaps: one fix round.","src":"scripts/ishikari-finish.js","id":"judge","code":"r4s2","name":"Judge ant","x":400,"y":1520},{"about":"Builds the judge's gaps as one fix on top of the merged scratch copy.","src":"scripts/ishikari-finish.js","id":"judge-fix-worker","code":"r4s3","name":"Worker ant","x":500,"y":1610},{"about":"Checks the fix and runs the tests. A failed fix keeps its branch and the verdict says why.","src":"scripts/ishikari-finish.js","id":"judge-fix-detective","code":"r4s4","name":"Detective ant","x":660,"y":1610},{"about":"Fast-forwards the scratch copy to the fix. The fix lands only through this fast-forward.","src":"scripts/ishikari-finish.js (merger-ant:judge-fix)","id":"judge-fix-merger","code":"r4s5","name":"Merger ant","x":820,"y":1610},{"about":"Scores the run a second time. Still below 7: main moves anyway and the verdict is flagged. The judge never blocks main.","src":"scripts/ishikari-finish.js","id":"judge-again","code":"r4s6","name":"Judge ant","x":1000,"y":1610},{"about":"Fast-forwards main, which git refuses if it would overwrite local edits. Removes the worktrees, appends the stage's logbook rows, and runs checkCommand when it is set.","src":"scripts/ishikari-finish.js (Main phase)","id":"finisher","code":"r4s7","name":"Finisher ant","x":1180,"y":1520},{"about":"Moves only as a fast-forward, never a merge commit, and is never pushed. Push it yourself when you are happy.","src":"SKILL.md#4-finish","id":"main","code":"r4s8","name":"MAIN","x":1340,"y":1520},{"about":"The finisher ant runs the repo's saved checkCommand, only when main moved and the command is set. A failure starts one check-fix round. The check-fix round is one build round from the moved main, as a new task named check-fix. If the check still fails after it, the run stops and reports the output, and requirements are not marked done.","src":"ishikari.py config <state> checkCommand <cmd>","id":"check","code":"r4s9","name":"checkCommand","x":1580,"y":1520},{"about":"The main session runs ishikari.py req done with the :ID:s kept in planning, once the check passed or there is none. Skipped when the repo has no requirements file.","src":"scripts/ishikari.py (req done)","id":"req-done","code":"r4s10","name":"req done","x":1780,"y":1520}];
var W=2000,H=1960,pn=document.getElementById('pn'),box=pn.firstChild;
function show(i){var d=D[i];box.querySelector('b').textContent=d.name;box.querySelector('small').textContent=d.id+' · '+d.code;box.querySelector('p').textContent=d.about;
 box.querySelector('code').textContent=d.src;pn.classList.add('on');
 var h=box.offsetHeight||200,x=d.x+30,y=d.y-20;if(x+420>W-10)x=d.x-450;if(x<10)x=10;if(y+h>H-10)y=H-10-h;if(y<10)y=10;
 pn.setAttribute('x',x);pn.setAttribute('y',y);pn.setAttribute('height',h+4);}
function hide(){pn.classList.remove('on');}
document.querySelectorAll('.st').forEach(function(g){
 g.addEventListener('click',function(e){e.stopPropagation();show(+g.dataset.i);});
 g.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();show(+g.dataset.i);}});});
pn.addEventListener('click',function(e){e.stopPropagation();if(e.target.tagName==='i')hide();});
document.addEventListener('click',hide);
document.addEventListener('keydown',function(e){if(e.key==='Escape')hide();});
function fromHash(){var id=location.hash.replace(/^#(st-)?/,'');for(var i=0;i<D.length;i++)if(D[i].id===id||D[i].code===id){show(i);return;}}
window.addEventListener('hashchange',fromHash);fromHash();
})();
